#include <bits/stdc++.h>
using namespace std;

#define MAX 100005
typedef pair<int, int> PII;

map<PII, int> EdgeMap;
vector<PII> Graph[MAX];
bool Visited[MAX];
vector<pair<int, int>> Edges;
bool isPossible;

void dfs(int vertex, int parent = -1, int direction = 0) {
    Visited[vertex] = true;
    for(auto &edge : Graph[vertex]) {
        int to = edge.first, edgeDirection = edge.second;
        if(to == parent) continue; // Ignore the parent to avoid revisiting
        if(Visited[to]) {
            if(direction + edgeDirection == 0) isPossible = false; // Conflicting directions detected
            continue;
        }
        if(edgeDirection == 0) { // Edge direction is undefined
            edge.second = 1; // Assign a direction
            int index = EdgeMap[{vertex, to}]; // Retrieve edge index from map
            Edges[index].second = 1; // Mark edge direction explicitly in the global list
            dfs(to, vertex, 1);
        } else {
            // Continue DFS with the set direction
            dfs(to, vertex, direction + edgeDirection);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int Tests;
    cin >> Tests;
    while(Tests--) {
        int nodes, edges;
        cin >> nodes >> edges;
        EdgeMap.clear();
        fill(Graph, Graph + nodes + 1, vector<PII>());
        fill(Visited, Visited + nodes + 1, false);
        Edges.clear();
        isPossible = true;

        for(int i = 0; i < edges; ++i) {
            int from, to;
            cin >> from >> to;
            Graph[from].push_back({to, 0}); // Add bidirectional edge without specified direction
            Graph[to].push_back({from, 0}); // Similarly here
            EdgeMap[{from, to}] = EdgeMap[{to, from}] = i; // Map the edge to its index
            Edges.emplace_back(from, 0); // Add edge to list with a placeholder direction
        }

        for(int i = 1; i <= nodes; ++i) {
            if(!Visited[i]) dfs(i);
        }

        if(!isPossible) cout << "IMPOSSIBLE\n";
        else {
            for(auto &pair : Edges) {
                int node = pair.first, dir = pair.second;
                cout << node << " " << (dir > 0 ? EdgeMap[{node, pair.first}] : EdgeMap[{pair.first, node}]) + 1 << "\n";
            }
        }

    }

    return 0;
}
