bool depthFirstSearch(int current_node, int target_Node) {
    if (current_node == target_Node) return true;
    visited[current_node] = true;
    for (auto& tour : adjacency_list[current_node]) {
        if (!tour.is_used && !visited[tour.destination]) {
            if (depthFirstSearch(tour.destination, target_Node)) return true;
        }
    }
    return false;
}

bool isReachable(int node, Tour& tour) {
    tour.is_used = true;
    memset(visited, 0, sizeof(visited));
    bool result = depthFirstSearch(node, tour.destination);
    tour.is_used = false;
    return result;
}

int calculateEndTime(Tour& tour, int current_time) {
    return current_time + tour.duration;
}

int depthFirstSearchWithTime(int node, int current_time) {
    int minimum_time = INFINITY;
    for (auto& tour : adjacency_list[node]) {
        if (!tour.is_used && isReachable(node, tour)) {
            tour.is_used = true;
            int end_time = calculateEndTime(tour, current_time);
            minimum_time = min(minimum_time, depthFirstSearchWithTime(tour.destination, end_time));
            tour.is_used = false;
        }
    }
    return (minimum_time == INFINITY) ? current_time : minimum_time;
}

