struct point {
    ld x, y, z;
    point(ld x = 0, ld y = 0, ld z = 0) : x(x), y(y), z(z) {}
};

ld square(ld value) {
    return value * value;
}

ld magnitude(point p) {
    return sqrt(square(p.x) + square(p.y) + square(p.z));
}

ld distance(point a, point b) {
    return magnitude(a - b);
}

point operator+(point a, point b) {
    return point(a.x + b.x, a.y + b.y, a.z + b.z);
}

point operator-(point a, point b) {
    return point(a.x - b.x, a.y - b.y, a.z - b.z);
}

point operator*(point a, ld scalar) {
    return point(a.x * scalar, a.y * scalar, a.z * scalar);
}

ld dot_product(point a, point b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

point cross_product(point a, point b) {
    return point(a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x);
}

int N, S;
point positions[MAX_NODES], velocities[MAX_NODES];
ld distances[MAX_NODES];
bool visited[MAX_NODES];

bool dijkstra(ld currentTime) {
    for(int i = 0; i < N; ++i) {
        distances[i] = INFINITY;
        visited[i] = false;
    }

    priority_queue<pair<ld, int>, vector<pair<ld, int>>, greater<pair<ld, int>>> queue;
    queue.push({0, 0});
    distances[0] = 0;

    while (!queue.empty()) {
        int current = queue.top().second; queue.pop();
        if (visited[current]) continue;
        visited[current] = true;

        for (int i = 0; i < N; ++i) {
            if (i == current) continue;
            ld edgeWeight = distance(positions[current] + velocities[current] * currentTime, positions[i] + velocities[i] * currentTime);
            if (edgeWeight <= S * currentTime && distances[i] > distances[current] + edgeCanBeConvertedToTexttWeight) {
                distances[i] = distances[current] + edgeWeight;
                queue.push({distances[i], i});
            }
        }
    }

    return distances[N - 1] != INFINITY;
}

ld binary_search_for_time() {
    ld left = 0, right = INFINITY, mid;
    while (right - left > EPSILON) {
        mid = (left + right) / 2;
        if (dijkstra(mid)) right = mid;
        else left = mid + EPSILON;
    }
    return right;
}

