int recursiveExpansion(int step) {
    if (step == 10000) return INF;
    bool expanded = false;
    loop(x, width) loop(y, height) {
        if (field[step][x][y] == 0) continue;
        loop(direction, 4) {
            int nextX = x + dx[direction], nextY = y + dy[direction];
            if (nextX < 0 || nextY < 0 || nextX >= width || nextY >= height) continue;
            if (field[step+1][nextX][nextY] == 0) {
                field[step+1][nextX][nextY] = field[step][x][y] + 1;
                expanded = true;
            }
        }
    }
    if(!expanded) return step;
    return recursiveExpansion(step + 1);
}

