#include <utility>
#include <algorithm>
using namespace std;

typedef long long LL;
typedef unsigned long long ULL;
typedef long double LD;
typedef vector<int> VI;
typedef pair<int,int> PII;

#define REP(i,n) for(int i=0;i<(n);++i)
#define SIZE(c) ((int)((c).size()))
#define FOR(v, c) for(auto v = (c).begin(); v != (c).end(); ++v)

const int INF = 1e9;

int H, W, M;
vector<VI> mapData, waterLevel;
vector<vector<bool>> visited;

void solveCase(int caseID) {
    cin >> H >> W >> M;
    mapData = vector<VI>(H+4, VI(W+4, INF));
    waterLevel = vector<VI>(H+4, VI(W+4, 0));
    visited = vector<vector<bool>>(H+4, vector<bool>(W+4, false));

    REP(i, H) REP(j, W) cin >> mapData[i+2][j+2];

    auto compare = [&](PII a, PII b) {
        return mapData[a.first][a.second] + waterLevel[a.first][a.second] > mapData[b.first][b.second] + waterLevel[b.first][b.second];
    };
    priority_queue<PII, vector<PII>, decltype(compare)> priorityQueue(compare);

    REP(i, H+4) REP(j, W+4) priorityQueue.push({i, j});

    LL days = 0;
    while (true) {
        bool isStable = true;
        vector<vector<LL>> adjustments(H+4, vector<LL>(W+4, 0));

        while (!priorityQueue.empty()) {
            auto [x, y] = priorityQueue.top(); priorityQueue.pop();
            if (visited[x][y] || x < 2 || y < 2 || x >= H+2 || y >= W+2) continue;
            visited[x][y] = true;

            int waterHeight = waterLevel[x][y] + mapData[x][y];
            int minWaterHeight = INF;
            for (int dx = -1; dx <= 1; ++dx)
                for (int dy = -1; dy <= 1; ++dy) 
                    if (abs(dx) + abs(dy) == 1)
                        minWaterHeight = min(minWaterHeight, waterLevel[x+dx][y+dy] + mapData[x+dx][y+dy]);

            if (minWaterHeight < INF && waterHeight - minWaterHeight > M) {
                adjustments[x][y] = min((LL)M, waterHeight - minWaterHeight);
                isStable = false;
            }
        }

        if (isStable) break;

        REP(i, H+4) REP(j, W+4) {
            if (adjustments[i][j] > 0) {
                waterLevel[i][j] -= adjustments[i][j];
                REP(dx, 3) REP(dy, 3) 
                    if (abs(dx-1) + abs(dy-1) == 1)
                        priorityQueue.push({i+dx-1, j+dy-1});
            }
        }

        REP(i, H+4) REP(j, W+4) visited[i][j] = false;
        days++;
    }

    cout << "Case #" << caseID << ": " << days << "\n";
}

int main() {
    int testCases;
    cin >> testCases;
    for (int i = 1; i <= testCases; ++i) solveCase(i);
    return 0;
}
