void compute() {
    allChances.clear();
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < c[i]; j++) {
            allChances.push_back(prob[i]);
        }
    }
    sort(allChances.rbegin(), allChances.rend());
    memset(dp1, 0, sizeof(dp1));
    dp1[0][0] = 1;
    int max_combinations = (1 << min(m, static_cast<int>(allChances.size()))) - 1;
    for(int combination = 0; combination <= max_combinations; combination++) {
        for(int j = 0; j < 2; j++) {
            if(dp1[combination][j] > 0) {
                for(unsigned int k = 0; k < allChances.size(); k++) {
                    if(!(combination & (1 << k))) {
                        int next_combination = combination | (1 << k);
                        dp1[next_combination][j] = max(dp1[next_combination][j], dp1[combination][j] * (1 - allChances[k]));
                        dp1[next_combination][j^1] = max(dp1[next_combination][j^1], dp1[combination][j] * allChances[k]);
                    }
                }
            }
        }
    }
    double maximumProb = 0;
    for(int i = 0; i <= max_combinations; i++) {
        maximumProb = max(maximumProb, dp1[i][1]);
    }
    cout << fixed << setprecision(10) << maximumProb << endl;
}

