    return sqrt((x[i] - x[j]) * (x[i] - x[j]) + (y[i] - y[j]) * (y[i] - y[j]));
}

int determine_better(int i, int j, int k, double direction) {
    double angle1 = atan2(y[i] - y[k], x[i] - x[k]) - direction;
    double angle2 = atan2(y[j] - y[k], x[j] - x[k]) - direction;
    if (angle1 < 0) angle1 += 2 * M_PI;
    if (angle2 < 0) angle2 += 2 * M_PI;
    if (angle1 < angle2) return i;
    if (angle1 > angle2) return j;
    return distance(i, k) < distance(j, k) ? i : j;
}

int proceed(int k, double radius, double direction) {
    int count = 1;
    int best = NIL;
    REP(i, n) {
        if (distance(k, i) <= radius) {
            if (best == NIL || determine_better(i, best, k, direction) == i) {
                best = i;
            }
        }
    }
    if (best != NIL) count += proceed(best, radius, direction + M_PI / 6);
    return count;
}

