using namespace std;

ifstream inStream("input.txt");
ofstream outStream("output.txt");

const int MAX_SIZE = 520;
int testCases, rows, columns, hexValue, squareCount;
int grid[MAX_SIZE][MAX_SIZE], height[MAX_SIZE][MAX_SIZE], width[MAX_SIZE][MAX_SIZE], largestSquare[MAX_SIZE][MAX_SIZE], squaresFound[MAX_SIZE][MAX_SIZE], squareSums[MAX_SIZE];
char hexString[MAX_SIZE];

struct Square {
    int x, y, size;
    Square(int x, int y, int size) : x(x), y(y), size(size) {}
};

bool operator < (Square a, Square b) {
    if (a.size != b.size) return a.size < b.size;
    if (a.x != b.x) return a.x < b.x;
    return a.y < b.y;
}

priority_class<Square> priorityQueue;

void readGrid() {
    inStream >> rows >> columns;
    memset(grid, 0, sizeof(grid));
    for (int i = 1; i <= rows; ++i) {
        inStream >> hexString;
        for (int j = 0; j < columns; ++j) {
            if (hexString[j] >= '0' && hexString[j] <= '9') hexValue = hexString[j] - '0';
            else hexValue = hexString[j] - 'A' + 10;
            for (int k = 0; k < 4; ++k) grid[i][4 * j + 3 - k] = (hexValue >> k) & 1;
        }
    }
    columns *= 4;
}

void calculateDP() {
    memset(height, 0, sizeof(height));
    memset(width, 0, sizeof(width));
    memset(largestSquare, 0, sizeof(largestSquare));
    for (int i = 1; i <= rows; ++i) for (int j = 1; j <= columns; ++j) {
        if (grid[i][j] == grid[i-1][j]) height[i][j] = height[i-1][j] + 1;
        else height[i][j] = 1;
        if (grid[i][j] == grid[i][j-1]) width[i][j] = width[i][j-1] + 1;
        else width[i][j] = 1;
        if (grid[i][j] == grid[i-1][j-1]) {
            int temporary = min(largestSquare[i-1][j-1], min(width[i][j], height[i][j]));
            largestSquare[i][j] = temporary + 1;
        }
        else largestSquare[i][j] = 1;
        priorityQueue.push(Square(i, j, largestSquare[i][j]));
    }
}

void solve() {
    while (!priorityQueue.empty()) {
        Square s = priorityQueue.top(); priorityQueue.pop();
        bool valid = true;
        for (int i = s.x - s.size + 1; valid && i <= s.x; ++i)
            for (int j = s.y - s.size + 1; valid && j <= s.y; ++j)
                if (squaresFound[i][j]) valid = false;
        if (!valid) continue;
        for (int i = s.x - s.size + 1; i <= s.x; ++i)
            for (int j = s.y - s.size + 1; j <= s.y; ++j)
                squaresFound[i][j] = 1;
        squareSums[s.size]++;
    }
    squareCount = 0;
    for (int i = 1; i <= MAX_SIZE; ++i) if (squareSums[i]) ++squareCount;
    outStream << squareCount << '\n';
    for (int i = MAX_SIZE; i >= 1; --i) if (squareSums[i]) outStream << i << " " << squareSums[i] << '\n';
}

int main() {
    inStream >> testCases;
    while (testCases--) {
        memset(squareSums, 0, sizeof(squareSums));
        memset(squaresFound, 0, sizeof(squaresFound));
        readGrid();
        calculateDP();
        solve();
    }
    return 0;
}
