void Calc() {
    // Iterate through all possible ranges starting from 1 up to the difference between P and L
    for (int range = 1; range <= P - L; range++) {
        // Iterate through each possible starting point within the allowed bounds
        for (int start = L; start + range <= P; start++) {
            int end = start + range;
            // If the current segment meets the base condition, set its answer to 0
            if (start == 1 || C * start >= end) {
                ans[start][end] = 0;
            } else {
                // Initialize the current answer to a very high value to simplify minimum calculation
                ans[start][end] = 1e9;
                // Iterate through all possible midpoints to split the current segment
                for (int k = start; k < end; k++) {
                    // Update the answer with the minimum steps required for both halves of the segment
                    ans[start][end] = MIN(ans[start][end], 1 + MAX(ans[start][k], ans[k + 1][end]));
                }
            }
        }
    }
}

