            maxValue = sum;
            maxFrequency = 1;
        } else if (sum == maxValue) {
            maxFrequency++;
        }
        return;
    }
    for (int i = 0; i < n; ++i) {
        int prefixLength = 1;
        bool unique = false;
        while (prefixLength <= sequences[position].size() && !unique) {
            if (groups[i].find(sequences[position].substr(0, prefixLength)) == groups[i].end()) unique = true;
            else prefixLength++;
        }
        if (unique) {
            groups[i].insert(sequences[position].substr(0, prefixLength));
            search(position + 1, groups, sum + prefixLength);
            groups[i].erase(sequences[position].substr(0, prefixLength));
        } else {
            search(position + 1, groups, sum);
        }
    }
}

int main() {
