    ofstream cout("output.txt");

    int testCases;
    cin >> testCases;
    while (testCases--) {
        cin >> m >> n;
        sequences.resize(m);
        matrix.clear(); matrix.resize(n);
        for (int i = 0; i < m; ++i) cin >> sequences[i];
        vector<set<string>> groups(n);
        maxValue = -1, maxFrequency = 0;
        search(0, groups);
        cout << maxValue << ' ' << maxFrequency << '\n';
    }
    return 0;
}
