using namespace std;

const int MOD = 100003;
int memo[600][600]; // Renaming dp to memo for clarity

bool isValid(int currentPos, int prevPos, int maxMark) {
    return maxMark - currentPos >= currentPos - prevPos;
}

int computePermutation(int delta) {
    long long factorial = 1;
    for (int i = 2; i <= delta; i++) {
        factorial = (factorial * i) % MOD;
    }
    return factorial;
}

int calculate(int currentPos, int prevPos, int maxMark) {
    if (!isValid(currentPos, prevPos, maxMark)) return 0;
    return computePermutation(maxMark - prevPos - 1);
}

int findSolutions(int maxMark, int currentPos) {
    if (currentPos == 0) return 1;
    if (maxMark <= 1) return 0;
    if (memo[maxMark][currentPos] != -1) return memo[maxMark][currentPos]; // Use memoization to save recomputation

    int totalSolutions = 0;
    for (int i = 0; i < currentPos; i++) {
        if (!isValid(currentPos, i, maxMark)) continue;
        totalSolutions = (totalSolutions + (long long)findSolutions(i, i) * calculate(currentPos, i, maxMark)) % MOD;
    }

    return memo[maxMark][currentPos] = totalSolutions;
}

int main() {
    int testCases, n;
    cin >> testCases;
    memset(memo, -1, sizeof(memo));
    for (int testCase = 1; testCase <= testCases; testCase++) {
        cin >> n;
        int finalResult = 0;
        for (int j = 1; j <= n; j++) {
            finalResult = (finalResult + findSolutions(n, j)) % MOD;
        }
        cout << "Case #" << testCase << ": " << finalResult << endl;
    }
    return 0;
}
