using namespace std;

const int MAXN = 5000;
int IDX[MAXN], N;
int REQ[MAXN][3];

struct TreeNode {
    int startX, startY, limitX, limitY, count;
    TreeNode *leftChild, *rightChild;
    TreeNode(int startX, int startY, int limitX, int limitY) : startX(startX), startY(startY), limitX(limitX), limitY(limitY), count(0), leftChild(NULL), rightChild(NULL) {}
    ~TreeNode() {
        delete leftChild;
        delete rightChild;
    }
};

bool isInBounds(TreeNode *node, int x, int y) {
    return x >= node->startX && x <= node->limitX && y >= node->startY && y <= node->limitY;
}

void insertPoint(TreeNode *node, int x, int y) {
    if(!isInBounds(node, x, y)) return;

    node->count++;
    int midX = (node->startX + node->limitX) / 2;
    int midY = (node->startY + node->limitY) / 2;

    if(x <= midX) {
        if(y <= midY) {
            if(!node->leftChild) node->leftChild = new TreeNode(node->startX, node->startY, midX, midY);
            insertPoint(node->leftChild, x, y);
        } else {
            if(!node->rightChild) node->rightChild = new TreeNode(node->startX, midY+1, midX, node->limitY);
            insertPoint(node->rightChild, x, y);
        }
    } else {
        if(y <= midY) {
            if(!node->leftChild) node->leftChild = new TreeNode(midX+1, node->startY, node->limitX, midY);
            insertPoint(node->leftChild, x, y);
        } else {
            if(!node->rightChild) node->rightChild = new TreeNode(midX+1, midY+1, node->limitX, node->limitY);
            insertPoint(node->rightChild, x, y);
        }
    }
}

int countPoints(TreeNode *node, int x, int y) {
    if(!node || node->startX > x || node->startY > y) return 0;
    if(node->limitX <= x && node->limitY <= y) return node->count;
    return countPoints(node->leftChild, x, y) + countPoints(node->rightChild, x, y);
}

bool sortByFirstRequest(int a, int b) {
    return REQ[a][0] < REQ[b][0];
}

int main() {
    ifstream fileInput("A-large.in");
    ofstream fileOutput("A-large.out");
    int T;
    fileInput >> T;

    for(int testcase = 1; testcase <= T; ++testcase) {
        fileInput >> N;

        for(int i = 0; i < N; ++i) {
            IDX[i] = i;
            for(int j = 0; j < 3; ++j) {
                fileInput >> REQ[i][j];
            }
        }

        sort(IDX, IDX + N, sortByFirstRequest);

        TreeNode* root = new TreeNode(0, 0, 10000, 10000);
        int result = 0;

        for(int i = 0; i < N; ++i) {
            int x = REQ[IDX[i]][1];
            int y = REQ[IDX[i]][2];
            insertPoint(root, x, y);
            for(int j = 0; j <= i; ++j) {
                int currentX = REQ[IDX[j]][1];
                int currentY = REQ[IDX[j]][2];
                int count = countPoints(root, currentX, currentY);
                int combinedHeight = currentX + currentY - count;
                result = max(result, combinedHeight);
            }
        }

        fileOutput << "Case #" << testcase << ": " << result << endl;
        delete root;
    }

    return 0;
}
