    int n = s.length(), v = 0;
    LOOP(i, n) {
        int c = s[i]-'a';
        if(!child[v][c]) child[v][c] = V++;
        v = child[v][c];
        sz[v]++;
    }
    contain[v]++;
}

ll computeFunction(vector<int> &v, int N) {
    memset(dp, 0, sizeof(dp));
    dp[0] = 1;
    LOOP(i, v.size()) for(int j = N; j >= v[i]; j--) {
        dp[j] = (dp[j] + dp[j-v[i]]) % MOD;
    }
    return dp[N];
}

void solve() {
