        for(int x: sizes) {
            combinations = combinations * C[sum][x] % MOD;
            sum -= x;
        }
        product = product * computeFunction(sizes, contain[i]) % MOD * combinations % MOD;
    }
    total = product;
    cout << total << ' ' << V-1 << endl;
}

