bool inRange(int y, int x) {
    return 0 <= y && y < H && 0 <= x && x < W;
}

int accumulatedWater(int y, int x) {
    if(!inRange(y, x)) return 0;
    return water[y][x];
}

bool isWalled(int y, int x) {
    if(!inRange(y,x) || visited[y][x]) return true;
    visited[y][x] = 1;
    bool ret = true;
    REP(dir, 4) {
        int ny = y + dy[dir], nx = x + dx[dir];
        if(height[y][x]+water[y][x] > height[ny][nx]+accumulatedWater(ny, nx) && !isWalled(ny, nx)) ret = false;
    }
    return ret;
}

void fillWater() {
    MEMSET(visited, 0);
    REP(y, H) REP(x, W) if(!visited[y][x] && isWalled(y, x)) water[y][x]++;
}

void erode() {
    int newHeight[505][505];
    MEMSET(newHeight, 0);
    REP(y, H) REP(x, W) {
        int lowest = height[y][x]+water[y][x];
        REP(dir, 4) {
            int ny = y + dy[dir], nx = x + dx[dir];
            lowest = min(lowest, height[ny][nx]+accumulatedWater(ny, nx));
        }
        newHeight[y][x] = max(0, height[y][x]-(height[y][x]+water[y][x]-lowest)/M);
    }
    memcpy(height, newHeight, sizeof(height));
}

void solve() {
    cin >> H >> W >> M;
    REP(y, H) REP(x, W) cin >> height[y][x];
    MEMSET(water, 0);
    for(;;) {
        int prevHeight[505][505];
        memcpy(prevHeight, height, sizeof(height));
        fillWater();
        erode();
        if(memcmp(prevHeight, height, sizeof(height)) == 0) break;
    }
    int rounds = 0;
    REP(y, H) REP(x, W) rounds += water[y][x];
    cout << rounds << endl;
