struct Interval {
    int start, finish;
    bool isScheduled;
    bool operator<(const Interval& other) const {
        return (finish < other.finish);
    }
} schedulesA[MAX], schedulesB[MAX];

int availableA, availableB, totalA, totalB, turnaroundTime;

int compareIntervals(const void* a, const void* b) {
    Interval* first = (Interval*)a;
    Interval* second = (Interval*)b;
    return first->start - second->start;
}

void allocateTrains(Interval schedules[], int& availableTrains, int totalSchedules) {
    for (int i = 0; i < totalSchedules; ++i) {
        if (!schedules[i].isScheduled) {
            schedules[i].isScheduled = true;
            for (int j = 0; j < totalSchedules; ++j) {
                if (!schedules[j].isScheduled && schedules[j].start >= schedules[i].finish + turnaroundTime) {
                    schedules[j].isScheduled = true;
                    break;
                }
            }
            availableTrains++;
        }
    }
}

int main() {
    ifstream inputFile("B-large.in");
    ofstream outputFile("B-large.out");
    int testCases;
    inputFile >> testCases;

    for (int testCase = 1; testCase <= testCases; ++testCase) {
        inputFile >> turnaroundTime >> totalA >> totalB;
        for (int i = 0; i < totalA; ++i) {
            inputFile >> schedulesA[i].start >> schedulesA[i].finish;
            schedulesA[i].isScheduled = false;
        }
        for (int i = 0; i < totalB; ++i) {
            inputFile >> schedulesB[i].start >> schedulesB[i].finish;
            schedulesB[i].isScheduled = false;
        }

        qsort(schedulesA, totalA, sizeof(Interval), compareIntervals);
        qsort(schedulesB, totalB, sizeof(Interval), compareIntervals);

        availableA = availableB = 0;
        allocateTrains(schedulesA, availableA, totalA);
        allocateTrains(schedulesB, availableB, totalB);

