    seq[0] = seq[1] = 1;
    for (int i = 2; i < maxn; ++i) {
        if (seq[i] == 2) {
            for (int j = i * 2; j < maxn; j += i) 
                seq[j] = 1;
        }
    }
    int j = 0;
    for (int i = 2; i < maxn; ++i) {
        if (seq[i] == 2) primes[j++] = i;
    }
}

