        int answer = -1;
        for (int prime : primes) {
            if (prime == 0) break;
            set<int> remainders;
            for (int i = 0; i < k; ++i) {
                remainders.insert(q[i] % prime);
            }
            if (remainders.size() == k || prime > pow(10, d)) {
                continue;
