bool VerifySolution() {
    for (int i = 1; i <= rows; ++i) {
        for (int j = 1; j <= columns; ++j) {
            int sum = 0;
            for (int k = 0; k < 9; ++k) {
                int nextRow = i + deltaX[k], nextColumn = j + deltaY[k];
                if (isWithinBounds(nextRow, nextColumn)) sum += currentGrid[nextRow][nextColumn];
            }
            if (sum != initialGrid[i][j]) return false;
        }
    }
    return true;
}

void FindMaximumBrightness() {
    maximumBrightness = 0;
    for (int mask = 0; mask < (1 << (rows * columns)); ++mask) {
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < columns; ++j) {
                int bit = (mask >> (i * columns + j)) & 1;
                currentGrid[i+1][j+1] = bit; // Adjusting to 1-based indexing
            }
