struct UnionFind {
    vector<int> parent;
    int size;

    UnionFind(int sz) : size(sz), parent(sz) {
        for(int i = 0; i < sz; i++) parent[i] = i;
    }

    int find(int i) {
        return i == parent[i] ? i : parent[i] = find(parent[i]);
    }

    bool unite(int i, int j) {
        i = find(i);
        j = find(j);
        if(i != j) {
            parent[i] = j;
            return true;
        }
        return false;
    }
