bool isZero(double v) {
    return fabs(v) < 1e-9;
}

double area(double x1, double y1, double x2, double y2, double x3, double y3) {
    return fabs(x1*(y2 - y3) + x2*(y3 - y1) + x3*(y1 - y2)) / 2.0;
}

double distance(double x, double y) {
    return sqrt(x*x + y*y);
}

void calculateAngle(double x1, double y0, double x2, double y2, double &cosTheta, double &sinTheta) {
    double dist1 = distance(x1, y0), dist2 = distance(x2, y2);
    cosTheta = (x1*x2 + y0*y2) / (dist1 * dist2);
    sinTheta = (x1*y2 - y0*x2) / (dist1 * dist2);
}

void solve() {
    cin >> x1 >> y1 >> x2 >> y2 >> x3 >> y3;
    cin >> xx1 >> yy1 >> xx2 >> yy2 >> xx3 >> yy3;

    double originalArea = area(0, 0, x2-x1, y2-y1, x3-x1, y3-y1);
    double targetArea = area(0, 0, xx2-xx1, yy2-yy1, xx3-xx1, yy3-yy1);

    // Calculating Translation
    double translationX = xx1 - x1;
    double translationY = yy1 - y1;

    // Calculating Scale factor
    double scaleFactor = sqrt(targetArea / originalArea);

    double cosAngle, sinAngle;
    // Determining Rotation angle
    calculateAngle(x2-x1, y2-y1, xx2-xx1, yy2-yy1, cosAngle, sinAngle);

    double transformedX = scaleFactor * (x2 - x1) * cosAngle - scaleFactor * (y2 - y1) * sinAngle + translationX;
    double transformedY = scaleFactor * (x2 - x1) * sinAngle + scaleFactor * (y2 - y1) * cosAngle + translationY;

