#define FOR_EACH(i, C) for (auto& i : C)

const int MAX_NODES = 2005; // Adjust based on problem constraints
int nodes, source, sink;
vector<int> graph[MAX_NODES];
int excess[MAX_NODES], height[MAX_NODES], current[MAX_NODES];

struct Edge {
    int to, capacity, flow;
    Edge* reverse;
    Edge(int to, int capacity, int flow) : to(to), capacity(capacity), flow(flow), reverse(nullptr) {}
};

void addEdge(int from, int to, int capacity, int reverseCapacity=0) {
    graph[from].emplace_back(Edge(to, capacity, 0));
    graph[to].emplace_back(Edge(from, reverseCapacity, 0));
    graph[from].back().reverse = &graph[to].back();
    graph[to].back().reverse = &graph[from].back();
}

void breadthFirstSearch(int start, int initialHeight) {
    fill(begin(height), end(height), -1);
    queue<int> queue;
    queue.push(start);
    height[start] = initialHeight;
    while (!queue.empty()) {
        int u = queue.front(); queue.pop();
        FOR_EACH(edge, graph[u]) {
            if (height[edge.to] == -1 && graph[edge.to][edge.reverse->to].capacity > graph[edge.to][edge.reverse->to].flow) {
                height[edge.to] = height[u] + 1;
                queue.push(edge.to);
            }
        }
    }
}

void push(int u, Edge &edge) {
    int deltaFlow = min(edge.capacity - edge.flow, excess[u]);
    edge.flow += deltaFlow;
    excess[u] -= deltaFlow;
    edge.reverse->flow -= deltaFlow;
    excess[edge.to] += deltaFlow;
}

void relabel(int u) {
    int minHeight = 2 * MAX_NODES;
    FOR_EACH(edge, graph[u]) {
        if (edge.capacity - edge.flow > 0)
            minHeight = min(minHeight, height[edge.to]);
    }
    if (minHeight < 2 * MAX_NODES) height[u] = minHeight + 1;
}

int maxFlow() {
    fill(begin(excess), end(excess), 0); excess[source] = INT_MAX;
    fill(begin(height), end(height), 0); height[source] = nodes;
    fill(begin(current), end(current), 0);
    breadthFirstSearch(sink, 0);

    int u = source;
    while (height[source] < nodes) {
        bool pushed = false;
        if (u != source && u != sink && excess[u] > 0) {
            for (int &i = current[u]; i < graph[u].size(); ++i) {
                Edge &edge = graph[u][i];
                if (edge.capacity - edge.flow > 0 && height[u] == height[edge.to] + 1) {
                    push(u, edge);
                    pushed = true;
                    if (excess[u] == 0) break;
                }
            }
        }
        if (!pushed) {
            relabel(u);
            current[u] = 0;
        }
        u = (u + 1) % nodes;
    }
    return excess[sink];
}

int gridToId(int x, int y, int width) {
    return x * width + y;
}

