#include <iostream>
using namespace std;

const long long MOD = 1000000007; // Modulus for the calculations
const int Maxn = 100007; // Maximum size for arrays
long long jie[Maxn], dao[Maxn]; // Arrays to store factorial values and their modular inverses
int prim[Maxn], top = 0, flag[Maxn], n, m; // Arrays for prime numbers, and various counters
typedef long long ll;

// Function to compute x raised to the power y under modulo MOD
ll powMod(ll x, ll y) {
    ll result = 1;
    while (y > 0) {
        if (y & 1) result = (result * x) % MOD;
        x = (x * x) % MOD; // Squaring the base
        y >>= 1; // Halving the exponent
    }
    return result;
}

// Precompute factorials and their modular inverses
void precomputeFactorials() {
    jie[0] = 1; // 0! is 1
    for (int i = 1; i < Maxn; i++) jie[i] = (jie[i - 1] * i) % MOD; // Compute factorial mod MOD
    // Compute modular inverses of the factorials
    dao[Maxn - 1] = powMod(jie[Maxn - 1], MOD - 2); 
    for (int i = Maxn - 2; i >= 0; i--) dao[i] = (dao[i + 1] * (i + 1)) % MOD;
}

// Combination function C(x, y) under modulo MOD
ll c(ll x, int y) {
    if (y > x) return 0;
    return jie[x] * dao[y] % MOD * dao[x - y] % MOD;
}

// Sieve of Eratosthenes for prime number generation
void generatePrimes() {
    for (int i = 2; i < Maxn; ++i) {
        if (!flag[i]) prim[top++] = i; // i is a prime number
        for (int j = 0; j < top && i * prim[j] < Maxn; ++j) {
            flag[i * prim[j]] = 1; // Mark multiples of prime numbers
            if (i % prim[j] == 0) break; // Optimization to stop marking if 'i' is a multiple of prim[j]
        }
    }
}

// Function to determine the sign based on prime factorization
int determineSign(int x) {
    int result = 1, last = -1, count = 0;
    while (x > 1) {
        if (flag[x] == last) return 0;
        if (last != -1 && last != flag[x]) count++;
        last = flag[x];
        x /= flag[x];
    }
    if (last != -1) count++;
    if (count & 1) result = -1;
    return result;
}

int main() {
    generatePrimes();
    precomputeFactorials();
    for (n = 1; n <= 100000; ++n) {
        m = max(1, (n >> 1) - 1);
        ll accumulator = 0;
        for (int i = 1; i * i <= n; ++i) {
            if (n % i == 0) {
                accumulator = (accumulator + MOD + determineSign(i) * c(n / i - 1, m - 1)) % MOD;
                if (i != n / i) accumulator = (accumulator + MOD + determineSign(n / i) * c(i - 1, m - 1)) % MOD;
            }
        }
        if (accumulator < 0) cout << n << " " << (int)accumulator << endl;
    }
    return 0;
}
