int determineOutcome(long long x, long long y) {
    if (x == y) return -1;
    if (y % x == 0 || x % y == 0) return 1;
    long long greatestCommonDivisor = gcd(x, y);
    if (greatestCommonDivisor == x - y || greatestCommonDivisor == y - x) return -1;
    if ((x > y && x < 2*y) || (y > x && y < 2*x)) return -determineOutcome(x-y, y);
    return 1;
}

int main() {
    int testCases, caseNumber = 1;
    cin >> testCases;
    while(testCases--) {
        long long startA, endA, startB, endB;
        cin >> startA >> endA >> startB >> endB;
        int winningScenarios = 0;
        for(long long a = startA; a <= endA; ++a) {
            for(long long b = startB; b <= endB; ++b) {
                if (determineOutcome(a, b) == 1) {
                    winningScenarios++;
                }
            }
        }
        cout << "Case " << caseNumber++ << ": " << winningScenarios << endl;
    }
    return 0;
}
