    if (remainingMoves == 0) {
        if (reachableNodes[currentNode] == visited.size()) {
            maxReachableNodesCount = max(maxReachableNodesCount, reachableNodes[currentNode]);
            maxReachableDistance++;
        }
        return;
    }
    for (int i = 0; i < graph[currentNode].size(); i++) {
        if (!visited.count(graph[currentNode][i])) {
            dfs(graph[currentNode][i], visited, remainingMoves - 1);
        }
    }
