    cin >> numChickens >> numRequired >> barnPosition >> timeLimit;
    for (int i = 0; i < numChickens; ++i) cin >> initialPositions[i];
    for (int i = 0; i < numChickens; ++i) cin >> speeds[i];

    if (numRequired == 0) {
        cout << "0" << endl;
        return;
    }

    // Reordering by decreasing initial positions
    for (int i = 0; i < numChickens; ++i) {
        for (int j = i + 1; j < numChickens; ++j) {
            if (initialPositions[i] < initialPositions[j]) {
                swap(initialPositions[i], initialPositions[j]);
                swap(speeds[i], speeds[j]);
            }
        }
    }

    int unableToReach = 0, swappingOperations = 0;
    for (int i = 0; i < numChickens && numRequired > 0; ++i) {
        if (initialPositions[i] + timeLimit * speeds[i] >= barnPosition) {
            --numRequired;
            swappingOperations += unableToReach;
        } else {
            ++unableToReach; // Counting chickens that can't reach in time but are ahead
        }
    }

    if (numRequired > 0) cout << "IMPOSSIBLE" << endl; // Some chickens can't make it in time
    else cout << swappingOperations << endl;
}

