bool isSeparable(double midpoint){
    double leftY = left[0].y, rightY = right[0].y;
    for (int i = 1; i < leftSidePoints; i++){
        if (left[i].x >= midpoint){
            leftY = interpolate(left[i - 1], left[i], midpoint);
            break;
