int calculateSum(Node *node) {
    if (node == NULL) return 0;
    return calculateSum(node->leftChild) + calculateSum(node->rightChild) + 1;
}

int countOuterNodes(Node *node) {
    if (node == NULL) return 0;
    int leftSum = calculateSum(node->leftChild);
    int rightSum = calculateSum(node->rightChild);
    if (leftSum == 0 || rightSum == 0) return max(leftSum, rightSum);
    return countOuterNodes(node->leftChild) + countOuterNodes(node->rightChild);
}

void constructTree(int current, int parent) {
