bool isValidQuantity(int ratio, int requirement, int available) {
    if (ratio == 0) return false;
    int minimum = requirement * 9 / 10;
    int maximum = requirement * 11 / 10;
    return available >= minimum * ratio && available <= maximum * ratio;
}

int calculateMaxKits(vector<int>& recipes, vector<vector<int>>& ingredients) {
    int totalKits = 0;
    int numOfRecipes = recipes.size();
    for (auto& ingredient : ingredients) {
        sort(ingredient.begin(), ingredient.end());
    }

    bool possibleToPrepare = true;
    while (possibleToPrepare) {
        vector<int> kitsPerRecipe;
        for (int i = 0; i < numOfRecipes; ++i) {
            int ratio = -1;
            for (int j = 0; j < ingredients[i].size(); ++j) {
                for (int servings = 1; servings <= 1000; ++servings) { // Assume up to 1000 servings can be prepared.
                    if (isValidQuantity(servings, recipes[i], ingredients[i][j])) {
                        ratio = servings;
                        ingredients[i].erase(ingredients[i].begin() + j);
                        break;
                    }
                }
                if (ratio != -1) break;
            }
            if (ratio == -1) {
                possibleToPrepare = false;
                break;
            } else {
                kitsPerRecipe.push_back(ratio);
            }
        }

        if (possibleToPrepare && !kitsPerRecipe.empty()) {
            totalKits += 1;
        }
    }
    return totalKits;
