    int sum = 0;
    for (char c : str) sum += c - '0';
    return sum > str.length();
}

bool validateUnique(const string &str) {
    int length = str.length();
    int weightedSum = 0;
    for (int i = 0; i < length; ++i) {
        weightedSum += (i + 1) * (str[i] - '0');
    }
    return weightedSum == length;
}

void explore(const string &str) {
    if (s.find(str) != s.end()) return;
    s.insert(str);
    if (validateUnique(str)) {
        ++dcount;
        return;
    }
    for (int i = 0; i < str.size(); ++i) {
        for (int j = '0'; j <= '9'; ++j) {
            string next = str;
            next[i] = j;
            if (!checkExpiry(next)) explore(next);
        }
    }
}

void generateNext(vector<int> prev, string temp, int x) {
    if(x == temp.size()){
        explore(temp);
        return;
    }
    for(int i = 0; i <= 9; i++) {
        if(prev[i] > 0){
            temp[x] = '0' + i;
            prev[i]--;
            generateNext(prev,temp,x+1);
            prev[i]++;
        }
    }
}

string transform(const string& str) {
    int count[10] = {};
    for (char c : str) count[c - '0']++;
    string result = "";
    for (char c : str) result += count[c - '0'] + '0';
    return result;
}

