// Dinic's algorithm for maximum flow
class DinicFlow {
private:
    struct Edge {
        int to, rev;
        long long flow, capacity;
    };

    vector<vector<Edge>> graph;
    vector<int> dist, queue, work;
    int nodeCount, source, sink;

    bool bfs_layer() {
        fill(dist.begin(), dist.end(), -1);
        dist[source] = 0;
        int qTail = 0;
        queue[qTail++] = source;
        for (int qHead = 0; qHead < qTail; qHead++) {
            int u = queue[qHead];
            for (auto &edge : graph[u]) {
                int v = edge.to;
                if (dist[v] < 0 && edge.flow < edge.capacity) {
                    dist[v] = dist[u] + 1;
                    queue[qTail++] = v;
                }
            }
        }
        return dist[sink] >= 0;
    }

    long long dfs_push(int u, long long flow) {
        if (u == sink) return flow;
        for (int &i = work[u]; i < SZ(graph[u]); ++i) {
            Edge &edge = graph[u][i];
            if (edge.capacity <= edge.flow) continue;
            int v = edge.to;
            if (dist[v] == dist[u] + 1) {
                long long df = dfs_push(v, min(flow, edge.capacity - edge.flow));
                if (df > 0) {
                    edge.flow += df;
                    graph[v][edge.rev].flow -= df;
                    return df;
                }
            }
        }
        return 0;
    }

public:
    DinicFlow(int n, int source, int sink) : nodeCount(n), source(source), sink(sink) {
        graph.resize(n); dist.resize(n); queue.resize(n); work.resize(n);
    }

    void addEdge(int from, int to, long long capacity) {
        graph[from].push_back({to, SZ(graph[to]), 0, capacity});
        graph[to].push_back({from, SZ(graph[from])-1, 0, 0}); // reverse edge for residual flow
    }

    long long findMaxFlow() {
        long long totalFlow = 0;
        while (bfs_layer()) {
            fill(work.begin(), work.end(), 0);
            while (long long flow = dfs_push(source, LLONG_MAX)) {
                totalFlow += flow;
            }
        }
        return totalFlow;
    }
};

