    ifstream inputFile("input.txt"); // Open the input file for reading
    ofstream outputFile("output.txt"); // Open the output file for writing

    inputFile >> testCases; // Read the number of test cases
    while (testCases--) {
        inputFile >> deleteCost >> insertCost >> maxChangeCost >> sequenceLength; // Read parameters deleteCost, insertCost, maxChangeCost, sequenceLength
        for (int i = 1; i <= sequenceLength; ++i) inputFile >> sequence[i]; // Read the sequence of n integers

        for (int i = 0; i <= sequenceLength; ++i)
            for (int j = 0; j <= 256; ++j)
                cost[i][j] = INF; // Initialize the DP array with infinity

        for (int j = 0; j <= 256; ++j)
            cost[0][j] = 0; // Set the base case

        for (int i = 1; i <= sequenceLength; ++i) {
            for (int j = 0; j <= 256; ++j) {
                if (cost[i-1][j] != INF) {
                    // Handling deletion
                    cost[i][j] = min(cost[i][j], cost[i-1][j] + deleteCost);
                    // Handling modification
                    for (int k = 0; k <= 256; ++k) {
                        if (abs(k - j) <= maxChangeCost || maxChangeCost == 0)
                            cost[i][k] = min(cost[i][k], cost[i-1][j] + abs(sequence[i] - k));
                        else if (maxChangeCost != 0)
                            cost[i][k] = min(cost[i][k], cost[i-1][j] + abs(sequence[i] - k) + insertCost);
                    }
                }
            }
        }

        int minimumCost = INF;
        for (int j = 0; j <= 256; ++j)
            minimumCost = min(minimumCost, cost[sequenceLength][j]); // Compute the minimum cost

        outputFile << minimumCost << endl; // Output the result to the file
    }

    inputFile.close(); // Close the input file
    outputFile.close(); // Close the output file

    return 0;
}
