    int mid = (l + r) >> 1;
    solve(l, mid);
    solve(mid + 1, r);
    vector<pair<int, int>> vec;
    for (int i = l; i <= mid; ++i) vec.emplace_back(p[i], i);
    for (int i = mid + 1; i <= r; ++i) vec.emplace_back(q[i], -i);
    sort(vec.begin(), vec.end(), cmp);
    ++flag;
    for (auto &it : vec) {
        if (it.second > 0) insert(it.second, it.second);
        else update(query(-it.second));
    }
