    // Identifying the minimum number of rides necessary
    int rides = 0, promos = 0;
    multiset<int> Queue;
    for (int i = 1; i <= N; ++i) {
        for (int id : CustomerSeats[i]) {
            Queue.insert(id);
        }
        while (!Queue.empty()) {
            int passengerCount = 0;
            for (int num : Queue) {
                if (!used[num]) {
                    used[num] = true;
                    passengerCount++;
                }
            }
            for (int i = 1; i <= passengerCount; ++i) {
                Queue.erase(Queue.begin());
            }
            fill_n(used, 1001, false);
            rides++;
        }
    }

    // Determining the necessary promotions
    for (int i = 1; i <= N; ++i) {
        int size = CustomerSeats[i].size();
        promos = max(promos, size - rides);
    }

    return {rides, promos};
}
