typedef long long LL;
const LL MOD = 1000000007LL;
LL ar[2000005], ar2[2000005];
int tc, ntc;
LL A, B;

LL generatePalindrome(int x) {
    LL result = x;
    while (x) {
        result = result * 10 + x % 10;
        x /= 10;
    }
    return result;
}

LL generateSemiPalindrome(int x) {
    LL result = x;
    x /= 10; // Omit the last digit
    while (x) {
        result = result * 10 + x % 10;
        x /= 10;
    }
    return result;
}

int main() {
    ifstream fin("input.txt");
    ofstream fout("output.txt");

    fin >> ntc;
    for (tc = 1; tc <= ntc; ++tc) {
        fin >> A >> B;
        int palindromeCount = 0;
        for (int i = 1; i <= 1000000; ++i) {
            LL fullPalindrome = generatePalindrome(i);
            LL halfPalindrome = generateSemiPalindrome(i);
            if (fullPalindrome >= A && fullPalindrome <= B) ar[palindromeCount++] = fullPalindrome;
            if (halfPalindrome >= A && halfPalindrome <= B) ar[palindromeCount++] = halfPalindrome;
        }
        sort(ar, ar + palindromeCount);
        if (palindromeCount == 0) {
            ar2[0] = B - A + 1;
            palindromeCount = 1;
        } else {
            for (int i = 0; i < palindromeCount - 1; ++i) {
                ar2[i] = (ar[i + 1] - ar[i]);
            }
            ar2[palindromeCount - 1] = (B - ar[palindromeCount - 1] + 1) + (ar[0] - A);
        }

        LL result = 0, evenSum = 0, oddSum = 0;
        for (int i = 0; i < palindromeCount; ++i) {
            if(i % 2 == 0) {
                evenSum += ar2[i];
                evenSum %= (2 * MOD);
            } else {
                oddSum += ar2[i];
                oddSum %= (2 * MOD);
            }
        }
        result = ((evenSum % MOD) * (oddSum % MOD)) % MOD;

        cout << "Case #" << tc << ": " << result << "\n";
        fout << "Case #" << tc << ": " << result << "\n";
    }

    fin.close();
    fout.close();
    return 0;
}
