using namespace std;

const double precision = 1e-12;
double area, width;
int lowerCount, upperCount, slices;
int lowerX[110], lowerY[110], upperX[110], upperY[110];

double interpolate(int* x, int *y, int index, double xValue) {
    if (fabs(x[index] - x[index-1]) < precision) return y[index];
    return y[index-1] + (y[index] - y[index-1]) * (xValue - x[index-1]) / (x[index] - x[index-1]);
}

double computeHeight(int lowerIndex, int upperIndex, double xValue) {
    double lowerYValue = interpolate(lowerX, lowerY, lowerIndex, xValue);
    double upperYValue = interpolate(upperX, upperY, upperIndex, xValue);
    return upperYValue - lowerYValue;
}

double solve(double current, double target) {
    double accumulatedArea = 0, segmentWidth = (width - current) / 100000, previous = current;
    for (int i = 0; i < 100000 && accumulatedArea < target; i++) {
        double midpoint = (previous + previous + segmentWidth) / 2, segmentHeight = 0;
        for (int lowerIndex = 1, upperIndex = 1; lowerIndex <= lowerCount || upperIndex <= upperCount;) {
            double x = min(lowerX[lowerIndex], upperX[upperIndex]);
            if (x > previous + segmentWidth) break;
            segmentHeight += computeHeight(lowerIndex, upperIndex, x);
            while (lowerIndex <= lowerCount && lowerX[lowerIndex] <= x) lowerIndex++;
            while (upperIndex <= upperCount && upperX[upperIndex] <= x) upperIndex++;
        }
        accumulatedArea += (segmentHeight * segmentWidth) / 2;
        previous += segmentWidth;
    }
    double left = previous - segmentWidth, right = previous, mid;
    while (right - left > precision) {
        mid = (left + right) / 2, accumulatedArea = 0, previous = current;
        for (int i = 0; i < 100000 && accumulatedArea < target; i++) {
            double midpoint = (previous + min(mid, previous + segmentWidth)) / 2, segmentHeight = 0;
            for (int lowerIndex = 1, upperIndex = 1; lowerIndex <= lowerCount || upperIndex <= upperCount;) {
                double x = min(lowerX[lowerIndex], upperX[upperIndex]);
                if (x > min(mid, previous + segmentWidth)) break;
                segmentHeight += computeHeight(lowerIndex, upperIndex, x);
                while (lowerIndex <= lowerCount && lowerX[lowerIndex] <= x) lowerIndex++;
                while (upperIndex <= upperCount && upperX[upperIndex] <= x) upperIndex++;
            }
            accumulatedArea += (segmentHeight * min(segmentWidth, mid - previous)) / 2;
            if (previous >= mid) break;
            previous += segmentWidth;
        }
        if (accumulatedArea < target) left = mid;
        else right = mid;
    }
    return (left + right) / 2;
}

