        for (int i = 1; i <= lowerCount; i++) cin >> lowerX[i] >> lowerY[i];
        for (int i = 1; i <= upperCount; i++) cin >> upperX[i] >> upperY[i];
        lowerX[0] = upperX[0] = 0;
        lowerY[0] = upperY[0] = lowerY[1];
        lowerX[lowerCount+1] = upperX[upperCount+1] = width;
        lowerY[lowerCount+1] = upperY[upperCount+1] = lowerY[lowerCount];
        lowerCount += 2;
        upperCount += 2;
        area = 0;
        solve(0, 20000000);
        double averageSliceArea = area / slices, divisionLine = 0;
        for (int i = 1; i < slices; i++) {
