const int INFINITY = 100000;
const int MAX_NODES = 20000; // Assuming the upper limit of nodes is 20,000

int gate[MAX_NODES], node[MAX_NODES], changeable[MAX_NODES], dp[MAX_NODES][2];

void optimizeGateOperations(int m, int v) {
    for (int i = (m - 1) / 2; i >= 1; --i) {
        if (gate[i] == 1) { // AND gate logic
            for (int j = 0; j < 2; ++j) {
                dp[i][j] = INFINITY;
                for (int k = 0; k < 2; ++k) {
                    for (int l = 0; l < 2; ++l) {
                        if ((k & l) == j) {
                            dp[i][j] = min(dp[i][j], dp[2 * i][k] + dp[2 * i + 1][l]);
                        }
                    }
                }
                if (changeable[i]) {
                    dp[i][j] = min(dp[i][j], dp[i][j ^ 1] + 1);
                }
            }
        } else { // OR gate logic
            for (int j = 0; j < 2; ++j) {
                dp[i][j] = INFINITY;
                for (int k = 0; k < 2; ++k) {
                    for (int l = 0; l < 2; ++l) {
                        if ((k | l) == j) {
                            dp[i][j] = min(dp[i][j], dp[2 * i][k] + dp[2 * i + 1][l]);
                        }
                    }
                }
                if (changeable[i]) {
                    dp[i][j] = min(dp[i][j], dp[i][j ^ 1] + 1);
                }
            }
        }
    }
    int minimumChanges = dp[1][v];
    if (minimumChanges >= INFINITY) {
        cout << "IMPOSSIBLE\n";
    } else {
        cout << minimumChanges << "\n";
    }
}

int main() {
    int testCases;
    cin >> testCases;
    for (int caseNumber = 1; caseNumber <= testCases; caseNumber++) {
        int m, v;
        cin >> m >> v;
        for (int i = 1; i <= (m - 1) / 2; ++i) {
            cin >> gate[i] >> changeable[i];
            node[i] = -1; // Initialize internal nodes
        }
        for (int i = (m + 1) / 2; i <= m; ++i) {
            cin >> node[i];
            changeable[i] = 0; // Leaf nodes cannot be changed
            dp[i][node[i]] = 0;
            dp[i][node[i] ^ 1] = INFINITY;
        }
        optimizeGateOperations(m, v);
    }
    return 0;
}
