    for (ll i = 0; i < k; i++) {
        res += (double)(a[i] + mn) / 2;
    }
    return res;
}

bool can(ll mn, ll k) {
    ll sum = 0;
    for (ll i = 0; i < k; i++) {
        if (mn < a[i]) return false;
        sum += mn - a[i];
    }
    return sum <= b;
}

ll find_mx(ll k) {
    ll lo = 0, hi = 1e9, mid;
    while (lo < hi) {
        mid = lo + (hi - lo + 1) / 2;
        if (can(mid, k)) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

