#define FOR_LOOP(i,a,b) for(int i=(a); i<=(b); ++i)
#define REPEAT(i,n) FOR_LOOP(i,0,(n)-1)
#define FOR_LOOP_DESC(i,a,b) for(int i=(a); i>=(b); --i)
#define COMPLETE(c) (c).begin(),(c).end()
#define SORT_VECTOR(c) sort(COMPLETE(c))
#define REVERSE_VECTOR(c) reverse(COMPLETE(c))
#define REMOVE_DUPLICATES(c) (c).erase(unique(COMPLETE(c)),(c).end())
