#define SIZE size()

typedef long long i64;
typedef vector<int> VectorInt;
typedef vector<VectorInt> VectorVectorInt;
typedef pair<int,int> PairIntInt;
typedef vector<PairIntInt> VectorPairIntInt;

class DisjointSet {
    VectorInt parent, rank;
public:
    DisjointSet(int n) : parent(n), rank(n, 0) {
        REPEAT(i, n) parent[i] = i;
    }

    int find(int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    }

    void link(int x, int y) {
        x = find(x); y = find(y);
        if(x == y) return;
        if(rank[x] < rank[y]) parent[x] = y;
        else {
            parent[y] = x;
            if(rank[x] == rank[y]) rank[x]++;
        }
    }
};

VectorInt primes;

bool isPrime(int number) {
    for(int prime : primes) {
        if(number % prime == 0) return false;
        if(prime * prime > number) break;
    }
    return true;
}

void solve(int start, int end, int threshold, int caseNumber) {
    DisjointSet ds(end - start + 1);
    FOR_LOOP(i, start, end) {
        for(int p : primes) {
            if(p >= threshold && i + p <= end && (i % p == 0)) ds.link(i - start, i + p - start);
            if(p >= end) break;
        }
    }

    int sets = 0;
    REPEAT(i, end - start + 1) {
        if(ds.find(i) == i) sets++;
    }

    cout << "Case #" << caseNumber << ": " << sets << endl;
}

int main() {
    ifstream cin("B-large.in");
    ofstream cout("B-large.out");

    for(int i = 2; i < 1000; ++i) {
        if(isPrime(i)) primes.PUSH_BACK(i);
    }

    int T, start, end, threshold;
    cin >> T;
    REPEAT(i, T) {
        cin >> start >> end >> threshold;
        solve(start, end, threshold, i + 1);
    }
    return 0;
