    bool processEntry(string input) {
        for(int i = 0; i < size; ++i) {
            if(entries[i] == input && !isMarked[i]) {
                isMarked[i] = true;
                markedCount++;
                if(markedCount == size) {
                    initiateNewRound(i);
                    return true;
                }
                return false;
            }
        }
        return false;
    }

