    cin >> coordinatesX[0] >> coordinatesY[0] >> coordinatesX[1] >> coordinatesY[1] >> n;
    for (int i = 0; i < n; ++i) {
        int xx, yy;
        cin >> xx >> yy;
        processPoint(xx, yy);
        results[i] = results[0];
    }
    return n;
}

