class FordFulkerson {
private:
    vector<vector<Edge>> graph;
    vector<bool> visited;

    int dfs(int vertex, int sink, int flow) {
        if (vertex == sink) return flow;
        visited[vertex] = true;
        for (int i = 0; i < graph[vertex].size(); ++i) {
            Edge &edge = graph[vertex][i];
            if (!visited[edge.to] && edge.capacity > 0) {
                int tempFlow = dfs(edge.to, sink, min(flow, edge.capacity));
                if (tempFlow > 0) {
                    edge.capacity -= tempFlow;
                    graph[edge.to][edge.reverseIndex].capacity += tempFlow;
                    return tempFlow;
                }
            }
        }
        return 0;
    }

public:
    FordFulkerson(int V) : graph(V), visited(V) {}

    void addEdge(int from, int to, int capacity) {
        graph[from].emplace_back(Edge{to, capacity, static_cast<int>(graph[to].size())});
