int recursiveSolve(vector<int>& d, int p2, int index) {
    if (index == N) return 0;
    int& current = d[index];
    int currentModulo = (current % (p2*2) + p2*2) % (p2*2);
    if (currentModulo == 0) return recursiveSolve(d, p2, index + 1);
    int toSubtract = p2*2 - currentModulo;
    if (current < toSubtract) goto failure;
    current -= toSubtract;
    int result = toSubtract / p2 + recursiveSolve(d, p2, index + 1);
    current += toSubtract;
    return min(result, recursiveSolve(d, p2*2, index));
failure:
