#include <cmath>
#include <vector>
#include <iostream>
#include <algorithm>

using namespace std;

const double pi = 3.14159265358979323846;
const double eps = 1e-9;

// Calculate the dot product of two vectors
double dotProduct(double ax, double ay, double az, double bx, double by, double bz) {
    return ax * bx + ay * by + az * bz;
}

// Calculate the cross product of two vectors, and store the result in (cx, cy, cz)
void crossProduct(double ax, double ay, double az, double bx, double by, double bz, double &cx, double &cy, double &cz) {
    cx = ay * bz - az * by;
    cy = az * bx - ax * bz;
    cz = ax * by - ay * bx;
}

// Normalize a vector
void normalize(double &x, double &y, double &z) {
    double length = sqrt(dotProduct(x, y, z, x, y, z));
    x /= length;
    y /= length;
    z /= length;
}

// Assess if the set of points satisfies a certain condition
bool checkPoints(vector<double> &x, vector<double> &y, vector<double> &z) {
    size_t n = x.size();
    for (size_t i = 0; i < n; ++i) {
        vector<double> angles;
        for (size_t j = 0; j < n; ++j) {
            if (i != j) {
                double bx, by, bz, tx, ty, tz;
                // Determine base vector
                crossProduct(x[j] - x[i], y[j] - y[i], z[j] - z[i], x[i], y[i], z[i], bx, by, bz);
                normalize(bx, by, bz);
                // Determine top vector
                crossProduct(x[i], y[i], z[i], bx, by, bz, tx, ty, tz);
                normalize(tx, ty, tz);
                if (dotProduct(bx, by, bz, tx, ty, tz) > eps)
                    return false; // Vectors are not orthogonal

                for (size_t k = 0; k < n; ++k) {
                    if (k != i) {
                        double projB = dotProduct(x[k] - x[i], y[k] - y[i], z[k] - z[i], bx, by, bz);
                        double projT = dotProduct(x[k] - x[i], y[k] - y[i], z[k] - z[i], tx, ty, tz);
                        angles.push_back(atan2(projT, projB));
                    }
                }
                sort(angles.begin(), angles.end());
                for (sizelet l = 0; l < angles.size() - 1; ++l) {
                    if (angles[l + 1] - angles[l] > pi) return false; // Gap detected
                }
                if(2 * pi + angles.front() - angles.back() > pi) return false; // Check for wrapping gap
            }
        }
    }
    return true; // All conditions are met
}

int main() {
    int t;
    cin >> t;
    for (int caseNum = 1; caseNum <= t; ++caseNum) {
        int n;
        cin >> n;
        vector<double> x(n), y(n), z(n);
        for (int i = 0; i < n; ++i) {
            cin >> x[i] >> y[i] >> z[i];
        }
        cout << "Case #" << caseNum << ": " << (checkPoints(x, y, z) ? "YES" : "NO") << endl;
    }
    return 0;
}
