void dfsReverse(int node, int forbidden, int &depth, vector<bool>& visited) {
    visited[node] = true;
    for (int neighbor : reverseGraph[node]) {
        if (neighbor != forbidden && !visited[neighbor]) {
            dfsReverse(neighbor, forbidden, ++depth, visited);
        }
    }
}

void strongConnect(int node) {
    index[node] = lowLink[node] = currentIndex++;
    stackContents[stackTop++] = node;
    inStack[node] = true;

    for (int neighbor : graph[node]) {
        if (index[neighbor] == -1) {
            strongConnect(neighbor);
            lowLink[node] = min(lowLink[node], lowLink[neighbor]);
        } else if (inStack[neighbor]) {
            lowLink[node] = min(lowLink[node], index[neighbor]);
        }
    }

    if (lowLink[node] == index[node]) {
        int v;
        do {
            v = stackContents[--stackTop];
            inStack[v] = false;
            componentID[v] = componentIndex;
        } while (node != v);
        componentIndex++;
    }
}

void tarjanAlgorithm() {
    componentIndex = stackTop = currentIndex = 0;
    fill(begin(index), end(index), -1);
    fill(begin(lowLink), end(lowLink), 0);
    fill(begin(inStack), end(inStack), 0);
    for (int u = 0; u < nodes; u++) {
        if (index[u] == -1) strongConnect(u);
    }
}

