    int res = 1 + BFS(BFF, seen, N, BFF[source] - 1, start, source); // Proceeding with the recursion to the next BFF.
    seen[source] = 0; // Resetting for alternate paths exploration.
    // Evaluating mutual relationship for possible chain extension.
    if (BFF[BFF[source] - 1] - 1 == source && BFF[source] - 1 != previous) {
        int maxLength = 0;
        for (int i = 0; i < N; ++i) {
            if (!seen[i]) {
                vector<int> tempSeen = seen;
                tempSeen[source] = 1; // Marking mutual relations as visited.
                tempSeen[BFF[source] - 1] = 1;
                maxLength = max(maxLength, BFS(BFF, tempSeen, N, i, i + 1, -1));
            }
        }
        res += maxLength;
    }
    return res;
}

int main() {
    int T;
    cin >> T;
    for (int t = 1; t <= T; ++t) {
        int N;
        cin >> N;
        vector<int> BFF(N);
        for (int i = 0; i < N; ++i) {
            cin >> BFF[i];
        }

        int result = 0;
        for (int j = 0; j < N; ++j) {
            vector<int> seen(N, 0);
            result = max(result, BFS(BFF, seen, N, j, j + 1, -1));
        }
        cout << "Case #" << t << ": " << result << endl;
    }
    return 0;
}

