using namespace std;

struct Node {
    int lane;      // Indicates the lane or state of a node
    double velocity;   // Node's velocity
    double position;   // Node's current position
};

double minTime;
int infiniteTimeFlag, numberOfNodes;
char laneState[20];
const double epsilon = 1e-9;
const int minimumDistance = 5;
const double infinity = 1e18;

void solve(vector<Node> nodes, double startTime, int ignoreNodeId) {
    double minRequiredTime = infinity, maxRequiredTime = 0;
    infiniteTimeFlag = 1;
    for (int i = 0; i < numberOfNodes; ++i) {
        if (i == ignoreNodeId) continue;
        for (int j = i + 1; j < numberOfNodes; ++j) {
            if (j == ignoreNodeId) continue;
            if (nodes[i].lane != nodes[j].lane) continue;
            double distanceBetweenNodes = fabs(nodes[i].position - nodes[j].position);
            if (distanceBetweenNodes < minimumDistance) return;
            double relativeVelocity = fabs(nodes[i].velocity - nodes[j].velocity);
            if (relativeVelocity < epsilon) continue;
            double timeToCollision = (minimumDistance - distanceBetweenNodes) / relativeVelocity;
            if (nodes[i].position > nodes[j].position) timeToCollision = (minimumDistance + distanceBetweenNodes) / relativeVelocity;
            if (timeToCollision > epsilon) {
                infiniteTimeFlag = 0;
                minRequiredTime = min(minRequiredTime, timeToCollision);
                maxRequiredTime = max(maxRequiredTime, timeToCollision);
            }
        }
    }
    if (infiniteTimeFlag) return;
    for (int i = 0; i < numberOfNodes; ++i) nodes[i].position += nodes[i].velocity * minRequiredTime;
    minTime += minRequiredTime;
    solve(nodes, startTime + minRequiredTime, -1);
}

int main() {
    ifstream inputFileStream("in.txt");
    ofstream outputFileStream("out.txt");
    int testCases;
    inputFileStream >> testCases;
    while (testCases--) {
        inputFileStream >> numberOfNodes;
        vector<Node> nodes(numberOfNodes);
        for (int i = 0; i < numberOfNodes; ++i) {
            inputFileStream >> laneState >> nodes[i].velocity >> nodes[i].position;
            nodes[i].lane = (laneState[0]=='L') ? 1 : 2;
        }
        minTime = 0;
        solve(nodes, 0, -1);
        if (infiniteTimeFlag) outputFileStream << "Possible\n";
        else outputFileStream << minTime << "\n";
    }
    return 0;
}
