    cin >> n >> m;
}

void solve() {
    memset(cnt, 0, sizeof(cnt));
    int res = 0;
    for (int s = 0; s < (1 << m); ++s) {
        bool valid = true;
        for (int i = 0; i < m; ++i) {
            mat[0][i] = ((s >> i) & 1) ? 2 : 3;
        }
        for (int i = 1; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                int adjacentMatches = 0;
                for (int k = 0; k < 4; ++k) {
                    int nx = i + dx[k], ny = j + dy[k];
                    if (inside(nx - 1, ny) && mat[nx - 1][ny] == mat[i - 1][j])
                        ++adjacentMatches;
                }
                mat[i][j] = (adjacentMatches >= 2) ? mat[i - 1][j] : 3 - mat[i - 1][j];
            }
        }
        for (int i = 0; i < n && valid; ++i) {
            for (int j = 0; j < m && valid; ++j) {
                int adjacentDifferences = 0;
                for (int k = 0; k < 4; ++k) {
                    int nx = i + dx[k], ny = j + dy[k];
                    if (inside(nx, ny) && mat[nx][ny] != mat[i][j])
                        ++adjacentDifferences;
                }
                if (adjacentDifferences > 2) valid = false;
            }
        }
        if (valid) ++res;
    }
    cout << res << "\n";
}

