        if (distanceX > precision && distanceY > precision) firstQuadrant++;
        if (distanceX > precision && distanceY < -precision) secondQuadrant++;
        if (distanceX < -precision && distanceY < -precision) thirdQuadrant++;
        if (distanceX < -precision && distanceY > precision) fourthQuadrant++;
    }
    if (firstQuadrant == pointsCount / 4 && secondQuadrant == pointsCount / 4 && thirdQuadrant == pointsCount / 4 && fourthQuadrant == pointsCount / 4) {
        results.push_back({-C * A / (A * A + B * B) - B * median / (A * A + B * B),
                           -C * B / (A * A + B * B) + A * median / (A * A + B * B)});
    }
}

void analyze(double A, double B, double C) {
    evaluateLine(A, B, C);
    evaluateLine(A, B, C + precision); // Slightly adjust coefficients
    evaluateLine(A, B, C - precision);
}

void process(int test) {
    cin >> pointsCount; // pointsCount actually accounts for 4 times the number of unique points due to duplicates
    xCoords.resize(pointsCount);
    yCoords.resize(pointsCount);
    for (int i = 0; i < pointsCount; i++) {
        cin >> xCoords[i] >> yCoords[i];
    }
    results.clear();
    for (int i = 0; i < points; i++) {
        for (int j = i + 1; j < pointsCount; j++) {
            double A = yCoords[j] - yCoords[i];
            double B = xCoords[i] - xCoords[j];
            double C = -A * xCoords[i] - B * yCoords[i];
            analyze(A, B, C);
        }
    }
    if (results.empty()) {
        cout << "IMPOSSIBLE\n";
    } else {
        for (auto& point : results) {
            cout << point.first << " " << point.second << "\n";
        }
    }
}

int main() {
