ull compute(int level, int prevDigit, int topConstraint, int lowConstraint) {
    if(level == size) return 1;
    ull &result = memo[level][prevDigit][topConstraint][lowConstraint];
    if(result != -1) return result;
    result = 0;
    for(int currentDigit = 0; currentDigit < b; ++currentDigit) {
        if(abs(currentDigit-prevDigit) <= 1) continue; // Making sure consecutive digits differ significantly
        bool isValid = true;
        if(level & 1) { // For odd levels
