            if(currentDigit <= lowConstraint) isValid = false;
        } else { // For even levels
            if(currentDigit >= digits[level]) isValid = false;
            if(currentDigit >= topConstraint) isValid = false;
        }
        if(isValid)
            result += compute(level + 1, currentDigit, max(topConstraint, currentDigit), min(low100Constraint, currentDigit));
    }
    return result;
}

