void solve(int size, int diff[], int remainder) {
    if (size == 1) {
        logResult(diff[0] + remainder);
        return;
    }
    int temp[1005];
    FOR(i, size - 1) temp[i] = diff[i + 1] - diff[i];
    bool consistent = true;
    FOR(i, size - 2) if (temp[i] != temp[0]) consistent = false;
    if (consistent) {
        logResult(remainder + diff[size - 1] + temp[0]);
        return;
    }
    if (size == 3 && diff[0] * diff[2] == square(diff[1])) {
        logResult(remainder * diff[2] / diff[1]);
        return;
    }
    solve(size - 1, temp, diff[size - 2]);
}

