                grid[i + 1][j] = '\\';
                grid[i + 1][j + 1] = '/';
            }
        }
    }

    bool incomplete = false;
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < columns; ++j) {
            if (grid[i][j] == '#') {
                incomplete = true;
                break;
            }
        }
        if (incomplete) break;
    }

    if (incomplete) {
        cout << "Impossible" << endl;
    } else {
        for (int i = 0; i < rows; ++i) {
            cout << grid[i] << endl;
        }
    }
}

