int simulateRace(int threshold, int required, int timeLimit) {
    int numRacers = locations.size();
    vector<pair<int, int>> racerPositions(numRacers);

    for (int i = 0; i < numRacers; ++i) {
        racerPositions[i].first = locations[i] + velocities[i] * timeLimit;
        racerPositions[i].second = velocities[i];
    }

    sort(racerPositions.begin(), racerPositions.end(), greater<>());

    int overtakes = 0, finished = 0;
    for (int i = 0; i < numRacers && finished < required; ++i) {
        if (racerPositions[i].first >= threshold) {
            ++finished;
            overtakes += i - finished + 1;
        }
    }

    if (finished < required) return -1;
    else return overtakes;
}

