void solve() {
    F[N] = 1;
    for(int i = N+1; i <= C; i++) {
        F[i] = 0;
        for(int j = 1; j <= N && i-j >= N; j++) {
            F[i] += (comb[i-1][j-1] / comb[C][N]) * F[i-j];
        }
        F[i] = (F[i] + 1) / (1 - comb[i-1][N-1] / comb[C][N]);
    }
    printf("Case %d: %.7f\n", caseNumber++, F[C]);
}

