            int currentPosition = 1; // Start from the root
            while(sizeOf(generated) < sizeOf(identifier)) {
                generated += '0' + currentPosition;
                if (connections[currentPosition].empty()) break; 
                int randomChoice = rand() % importance[currentPosition] - 1; // Decide next move
                if (randomChoice < 0) break;
                iterate(i, 0, sizeOf(connections[currentPosition])) {
                    int next = connections[currentPosition][i];
                    if (randomChoice < importance[next]) {
                        currentPosition = next;
                        break;
                    }
                    randomChoice -= importance[next];
                }
            }
            if (generated.find(c) != string::npos) ++occurrences;
        }
        cout << fixed << setprecision(6) << (double)occurrences / 10000.0 << '\n';
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    cin >> testCases;
    while(testCases--) solve();
}
