int E, R, N, v[MAXN]; // Energy, restoration rate, number of activities, values array.
map<int, map<int, int>> cache; // Memorization cache.

// Recursive solution with memorization for optimal energy usage.
int solve(int curE, int pos) {
    if (pos == N) return 0; // Base case: no more activities.
    if (cache.count(curE) && cache[curE].count(pos))
        return cache[curE][pos]; // Return cached result if available.

    int &res = cache[curE][pos] = 0; // Initialize result for the current state.
    for (int xpnd = 0; xpnd <= curE; ++xpnd) {
        int nxtE = min(E, curE - xpnd + R); // Calculate next energy level.
        res = max(res, solve(nxtE, pos + 1) + v[pos] * xpnd); // Maximize value.
    }
    return res; // Return the result for current state.
}

