        REP(i, N) scanf("%d", &v[i]); // Read values for activities.
        cache.clear(); // Clear cache for new test case.
        printf("Case #%d: %d\n", kase, solve(E, 0)); // Print result for the test case.
    }
    return 0; // End of program.
