// Swaps characters at positions i and j in buf
void swap(int i, int j) {
    char temp = buf[i];
    buf[i] = buf[j];
    buf[j] = temp;
}

// Comparison function for qsort, sorts in descending order
int compareDescending(const void *a, const void *b) {
    return (*(char*)b - *(char*)a);
}

// Rearranges characters in buf to form the next lexicographically greater sequence
void rearrangeSequence() {
    int i, j, len = strlen(buf);
    // Find the first character that breaks the decreasing trend
    for (i = 1; i < len; i++) {
        if (buf[i] < buf[i-1]) break;
    }
    // If sequence is in complete descending order, add a '0' at the end to increase its value
    if (i == len) {
        buf[len] = '0';
        buf[len+1] = '\0';
        len++;
    }
    // Find the character just greater than buf[i]
    for (j = 0; j < len; j++) {
        if (buf[j] > buf[i]) break;
    }
    // Swap and sort the prefix to get the next sequence
    swap(i, j);
    qsort(buf, i, sizeof(char), compareDescending);
}

int main() {
    int N_, k;
    scanf("%d", &N_);
    for (k = 1; k <= N_; k++) {
        scanf("%s", buf2);
        int len = strlen(buf2);
        // Reverse buf2 into buf
        for (int i = 0; i < len; i++) {
            buf[i] = buf2[len-1-i];
        }
        buf[len] = '\0';

        rearrangeSequence();

        // Reverse buf back into buf2 to print in correct order
        len = strlen(buf);
        for (int i = 0; i < len; i++) {
            buf2[i] = buf[len-1-i];
        }
        buf2[len] = '\0';

        printf("Case #%d: %s\n", k, buf2);
    }
    return 0;
}
