        g = gcd(p, q); // Compute gcd to simplify fraction
        p /= g; // Simplify numerator
        q /= g; // Simplify denominator

        // Check if denominator is a power of 2
        bool flag = false;
        for(i = 0; i <= 40; ++i) {
            if(q == pow2[i]) {
                flag = true;
                break;
