void depthFirstSearch(int x, int y) {
    marker[x][y] = 1; count++;
    loop(i, 4) {
        int nextX = x + directionX[i], nextY = y + directionY[i];
        if(nextX >= 0 && nextX < rows && nextY >= 0 && nextY < columns && !marker[nextX][nextY]) {
            depthFirstSearch(nextX, nextY);
