void explore(int x, int y) {
    if(x == rows) {
        clearArray(marker); count = 0; isValid = true; isInvalid = false;
        loop(i, rows) loop(j, columns) {
            if(!marker[i][j]) {
                count = 0;
                depthFirstSearch(i, j);
                if(count > 1) isValid = false;
            }
        }
        if(isValid && !isInvalid) totalSolutions++;
        return;
    }
    int nextX = (y + 1) < columns ? x : x + 1;
    int nextY = (y + 1) < columns ? y + 1 : 0;
    explore(nextX, nextY); // Option 1: Leave cell (x, y) unmarked.
    marker[x][y] = 2; explore(nextX, nextY); marker[x][y] = 0; // Option 2: Mark cell (x, y).
}

