        for (char ch : sequence) {
            frequencyCounter[ch]++;
        }

        int nextAvailableDigit = 1;
        // Assign a unique digit to each character in the sequence
        for (char ch : sequence) {
            if (hasBeenAssigned[ch] == 0) {
                digitAssignment[ch] = nextAvailableDigit;
                hasBeenAssigned[ch] = 1;
                if (nextAvailableDigit == 1) nextAvailableDigit = 0;
                else if (nextAvailableDigit == 0) nextAvailableDigit = 2;
                else nextAvailableDigit++;
            }
        }

        long long totalValue = 0;
        long long numericBase = digitAssignment.size();
        if (numericBase == 1) numericBase = 2; // If there's only one distinct character, adjust the base to 2
        long long currentPower = 1;

        // Convert the sequence into a number based on the assigned digits
        for (int idx = sequence.size() - 1; idx >= 0; --idx) {
            totalValue += digitAssignment[sequence[idx]] * currentPower;
            currentPower *= numericBase;
        }

        outputFile << "Case #" << caseNum << ": " << totalValue << endl;
    }

    inputFile.close();
    outputFile.close();

    return 0;
