bool depth_first_search(int x, int y) {
    if(x == height) return true; // Reached the bottom
    if(visited[x][y]) return false; // Already visited
    visited[x][y] = true;
    // Check the cell below
    if(x+1 < height && !path_valid[x+1][y] && depth_first_search(x+1, y)) return true;
    // Wrap around and check the left cell
    if(y == 0 && !path_valid[x][width-1] && depth_first_search(x, width-1)) return true;
    // Move to the right cell if it's not a barrier (wrap around scenario)
    if(y+1 < width && !path_valid[x][y+1] && depth_first_search(x, y+1)) return true;
    return false;
}

int calculate_paths() {
    cin >> height >> width >> barriers;
    memset(path_valid, 0, sizeof path_valid);
    repeat(i, barriers) {
