        cin >> x >> y;
        path_valid[x][y] = true; // Mark barriers
    }

    int paths_count = 0;
    repeat(i, width) {
        memset(visited, 0, sizeof visited);
        if(!path_valid[0][i] && depth_first_search(0, i)) paths_count++;
    }
    return paths_count;
}

