bool isCompatible(int i, int j) {
    for (int l = 0; l < dimensions; ++l) {
        if (matrix[i][l] == matrix[j][l])
            return false;
    }
    for (int l = 0; l < dimensions; ++l) {
        if (matrix[i][l] > matrix[j][l])
            return false;
    }
    return true;
}

bool verifySolution(bool candidate[20]) {
    for (int i = 0; i < total; ++i) {
        if (candidate[i]) {
            for (int j = 0; j < total; ++j) {
                if (candidate[j] && !compatible[i][j]) {
                    return false;
                }
            }
        }
    }
    return true;
}

void findSolution(int index, int currentMax) {
    if (index == total) {
        int count = 0;
        for (int i = 0; i < total; ++i) {
            if (tempSolution[i]) ++count;
        }
        if (count > maximumMatches) {
            maximumMatches = count;
            memcpy(bestSolution, tempSolution, sizeof(tempSolution));
        }
        return;
    }
    if (currentMax + total - index <= maximumMatches)
        return;

    tempSolution[index] = false;
    findSolution(index + 1, currentMax);
    tempSolution[index] = true;
    if (verifySolution(tempSolution)) {
        findSolution(index + 1, currentMax + 1);
    }
}

int main() {
    ifstream input("in.txt");
    ofstream output("out.txt");

    input >> testCase;
    while (testCase--) {
