            for (int j = 0; j < dimensions; ++j)
                input >> matrix[i][j];
        for (int i = 0; i < total; ++i)
            for (int j = i + 1; j < total; ++j)
                if (!isCompatible(i, j)) compatible[i][j] = compatible[j][i] = false;
        maximumMatches = 0;
        findSolution(0, 0);
        output << maximumMatches << '\n';
