void dfs(int x, int y) {
    if (cod[x][y]) return;  // If already labeled, return
    int min_h = a[x][y];
    int idx = -1;
    for (int dir = 0; dir < 4; ++dir) {
        int nx = x + dx[dir], ny = y + dy[dir];
        if (a[nx][ny] < min_h) {
            min_h = a[nx][ny];
            idx = dir;
        }
    }
    if (min_h < a[x][y]) {  // Move to the lowest neighbor
        dfs(x + dx[idx], y + dy[idx]);
        cod[x][y] = cod[x + dx[idx]][y + dy[idx]];
    } else cod[x][y] = c++;  // Assign a unique label to the basin and increment the basin label
}

