// Recursive function to compute the best outcome under given constraints
void Compute(int pos, int mask, ll sum = 0) {
    // If current sum exceeds limit f, terminate this branch
    if (sum > f) return;
    // If reached the halfway point, consider updating the result
    if (pos == n / 2) {
        res = max(res, sum);
        return;
    }
    // Iterate through all combinations not yet considered
    FOR(i, n) {
        if (!(mask & (1 << i))) {
            FOR(j, i) {
                if (!(mask & (1 << j))) {
                    Compute(pos + 1, mask | (1 << i) | (1 << j), sum + Absolute(x[i] - x[j]));
                }
            }
        }
    }
}

