const long double eps = 1e-9;

int main() {
    int number_of_tests;
    cin >> number_of_tests;
    while (number_of_tests--) {
        int n, k; // 'k' is mentioned but not utilized in this section; likely a component of the problem's specifications.
        long double u;
        cin >> n >> k >> u;
        vector<long double> probabilities(n);
        for (int i = 0; i < n; ++i) {
            cin >> probabilities[i];
        }
        sort(probabilities.rbegin(), probabilities.rend()); // Sorting in reverse to commence with the highest probability

        long double optimum = 0;
        for (int i = 0; i <= n; ++i) {
            long double sum = 0;
            for(int j = 0; j < i; ++j) {
                sum += probabilities[j];
            }
            long double to_distribute = i - sum; // Quantity to allocate
            if (to_distribute > u + eps) continue; // Proceed if it's not possible to evenly allocate 'u' among 'i' probabilities

            long double remaining = u - to_distribute;
            long double outcome = 1.0;
            if (i < n) {
                long double each_remaining = remaining / (n - i);
                bool achievable = true;
                for (int j = i; j < n; ++j) {
                    if (probabilities[j] + each_remaining > 1.0 + eps) {
                        achievable = false; // Distribution of the remaining amount would exceed 1
                        break;
                    }
                }
                if (achievable) {
                    for (int j = 0; j < i; ++j) {
                        outcome *= 1.0; // These have reached their maximum
                    }
                    for (int j = i; j < n; ++j) {
                        outcome *= min(1.0L, probabilities[j] + each_remaining);
                    }
                }
            } else {
                outcome = pow(1 + remaining / n, n); // If all probabilities can achieve 1
            }
            optimum = max(optimum, outcome);
        }

        cout.precision(17);
        cout << fixed << optimum << endl;
    }
    return 0;
}

