    for (int dr = -1; dr <= 1; ++dr) {
        for (int dc = -1; dc <= 1; ++dc) {
            if (dr == 0 && dc == 0) continue; // Skip staying in place
            if (processMove(aliceTurn, knightRow + dr, knightCol + dc, happyState)) return memo[aliceTurn][knightRow][knightCol][happyState] = !aliceTurn;
        }
    }
    return memo[aliceTurn][knightRow][knightCol][happyState] = aliceTurn;
}

int main() {
    ofstream outputFile("outcome.txt");
    memset(memo, -1, sizeof(memo)); // Initialize memoization table
    int testCases;
    cin >> testCases;
    for (int t = 1; t <= testCases; ++t) {
        cin >> rows >> cols;
        int knightRow, knightCol, happyState = 0; // Initial position of the knight and the happy state
        cin >> knightRow >> knightCol;
        --knightRow; --knightCol; // Adjusting for 1-indexed input
        if (canWin(true, knightRow, knightCol, happyState)) {
            outputFile << t << " A\n";
        } else {
            outputFile << t << " B\n";
        }
    }
