int points(int distance) {
    // Assuming the formula for points is specific
    LL result = static_cast<LL>(distance) * (distance - 1) / 2; // Example formula
    result %= MOD;
    return static_cast<int>(result);
}

int solve() {
    int N, M;
    cin >> N >> M;
    vector<pair<PairInt, int> > events; // {{start, end}, passengers}
    LL expected = 0;
    REP(i, M) {
        int origin, endpoint, passengers;
        cin >> origin >> endpoint >> passengers;
        events.emplace_back(make_pair(origin, endpoint), passengers);
        expected += points(endpoint - origin) * passengers % MOD;
        expected %= MOD;
    }

    sort(events.begin(), events.end());

    LL real = 0;
    map<int, int> counts; // {end, passengers}
    for (const auto &event : events) {
        int start = event.first.first;
        int end = event.first.second;
        int passengers = event.second;

        while (passengers > 0) {
            auto it = counts.begin();
            if (it == counts.end() || it->first > start) {
                counts[end] += passengers;
                break;
            } else {
                int can_use = min(it->second, passengers);
                it->second -= can_use;
                if (it->second == 0) counts.erase(it);
                passengers -= can_use;

                real += points(end - it->first) * can_use % MOD;
                real %= MOD;

                if (passengers > 0) {
                    counts[end] += passengers;
                }
            }
        }
    }

    return (expected - real + MOD) % MOD;
}

