        adjacencyList.PB(vector<PII>());
    }

    void parseExpression(int startNode, int endNode, int openingBracketPosition, int closingBracketPosition) {
        if (openingBracketPosition == closingBracketPosition) {
            adjacencyList[startNode].PB(MP(endNode, expression[openingBracketPosition] - '0'));
        } else {
            int midpoint = openingBracketPosition;
            while (midpoint < closingBracketPosition && expression[midpoint] != '(') ++midpoint;
            if (midpoint == closingBracketPosition) {
                adjacencyList[startNode].PB(MP(endNode, -1));
                for (int i = openingBracketPosition; i <= closingBracketPosition; ++i)
                    adjacencyList[startNode][SZ(adjacencyList[startNode])-1].second *= 10, adjacencyList[startNode][SZ(adjacencyList[startNode])-1].second += expression[i] - '0';
            } else {
                int balance = 1, i = midpoint;
                while (balance != 0) {
                    i++;
                    if (expression[i] == '(') balance++;
                    if (expression[i] == ')') balance--;
                }
                int nextMidpoint = i;
                addVertex();
                int newNode = SZ(adjacencyList) - 1;
                parseExpression(startNode, newNode, openingBracketPosition, midpoint - 1);
                parseExpression(newNode, endNode, midpoint + 1, nextMidpoint - 1);
                parseExpression(startNode, endNode, nextMidpoint + 1, closingBracketPosition);
            }
        }
    }

    void expand(vector<bool> &currentSet) {
        vector<bool> nextSet(SZ(adjacencyList), false);
        R(i, SZ(adjacencyList)) if (currentSet[i]) for (PII edge : adjacencyList[i]) nextSet[edge.first] = true;
        swap(currentSet, nextSet);
    }

    void expand(LL &bitmask) {
        LL newBitmask = 0;
        R(i, SZ(adjacencyList)) if ((bitmask >> i) & 1) for (PII edge : adjacencyList[i]) newBitmask |= (1LL << edge.first);
        bitmask = newBitmask;
    }

    T analyzeLength(LL bitmask, int length) {
        if (length == 0) return bitmask & 1;
        expand(bitmask);
        return analyzeLength(bitmask, length - 1);
    }

    void explorePrefixMatch(string pattern, int maxLength) {
        LL bitmask = 1;
        bool feasible = true;
        R(i, min(SZ(pattern), maxLength)) {
            if (pattern[i] == '?') expand(bitmask);
            else {
                LL updatedMask = 0;
                R(j, SZ(adjacencyList)) if ((bitmask >> j) & 1) {
                    for (PII edge : adjacencyList[j]) if (edge.second == pattern[i] - '0') updatedMask |= (1LL << edge.first);
                }
                bitmask = updatedMask;
                if (!bitmask) feasible = false;
            }
        }
        if (feasible) totalResult += analyzeLength(bitmask, maxLength - SZ(pattern));
    }

