        if (SZ(pattern) == remainingLength) {
            if (lowerBound <= currentValue && currentValue <= upperBound) totalResult++;
            return;
        }
        if (pattern[SZ(pattern) - remainingLength] == '?') {
            for (int digit = (remainingLength == 1 && lowerBound <= currentValue); digit < 10; ++digit)
                exhaustNumericalSearch(lowerBound, upperBound, multiplier, currentValue + digit * multiplier, pattern, remainingLength - 1);
        } else {
            int digit = pattern[SZ(pattern) - remainingLength] - '0';
            exhaustNumericalSearch(lowerBound, upperBound, multiplier, currentValue + digit * multiplier, pattern, remainingLength - 1);
        }
    }

