map<vector<set<string>>, int> configurations;

// Type definitions
using Trie = set<string>;
using Configuration = vector<Trie>;

// Function prototypes
Trie createTrie(const string &s) {
    Trie trie;
    string prefix = "";
    trie.insert(prefix);
    for (char ch : s) {
        prefix += ch;
        trie.insert(prefix);
    }
    return trie;
}

void search(int index, Configuration &current, int serverMask) {
    if (index == numStrings) {
        if (serverMask == (1 << numServers) - 1) { // If all servers are utilized
            configurations[current]++;
        }
        return;
    }
    for (int i = 0; i < numServers; ++i) {
        Configuration previous = current; // Preserve current state
        current[i].insert(available[index].begin(), available[index].end());
        search(index + 1, current, serverMask | (1 << i));
        current = previous; // Restore state
    }
}

void solve(int testCase) {
    cin >> numStrings >> numServers;
    available.clear();
    available.resize(numStrings);
    for (int i = 0; i < numStrings; ++i) {
        string s;
        cin >> s;
        available[i] = createTrie(s);
    }

    configurations.clear();
    Configuration current(numServers); // Current tested configuration

    search(0, current, 0);

    // Identify the maximum size and number of configurations
    int maxSize = 0, waysToAchieve = 0;
    for (const auto &config : configurations) {
        int size = 0;
        for (const auto &s : config.first) size += s.size();
        if (size > maxSize) {
            maxSize = size;
            waysToAchieve = config.second;
        } else if (size == maxSize) {
            waysToAchieve += config.second;
        }
    }

    cout << "Case #" << testCase << ": " << maxSize << " " << waysToAchieve << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    for (int t = 1; t <= T; ++t) {
        solve(t);
    }

    return 0;
}
