double interpolateUpperY(double x) {
    for (int i = 1; i < U; i++) {
        if (u[i].x + eps > x) {
            double verticalChange = u[i].y - u[i-1].y;
            double horizontalChange = u[i].x - u[i-1].x;
            return u[i-1].y + (x - u[i-1].x) * verticalChange / horizontalChange;
        }
    }
    return u[U-1].y; // adjusted to account for precision errors
}

double interpolateLowerY(double x) {
    for (int i = 1; i < L; i++) {
        if (l[i].x + eps > x) {
            double verticalChange = l[i].y - l[i-1].y;
            double horizontalChange = l[i].x - l[i-1].x;
            return l[i-1].y + (x - l[i-1].x) * verticalChange / horizontalChange;
        }
    }
    return l[L-1].y; // adjusted to account for precision errors
}

double calculateArea(double x1, double x2) {
    double upperBoundary = (interpolateUpperY(x1)+interpolateUpperY(x2)) / 2;
    double lowerBoundary = (interpolateLowerY(x1)+interpolateLowerY(x2)) / 2;
    return (upperBoundary - lowerBoundary) * (x2 - x1);
}

double findDivision(double segmentArea, double start) {
