const int MAXN = 10005;
const int MAXE = 40005;
const int INF = 1e9;

int E, V, ST, FN;
int e[MAXE], nxt[MAXE], cap[MAXE], st[MAXN], cur[MAXN], h[MAXN];
int n, m, ecnt, wt, ht, b, t;
int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};
bool block[105][105];

void add_edge(int p, int q, int f1, int f2) {
    e[ecnt] = q; cap[ecnt] = f1; nxt[ecnt] = st[p]; st[p] = ecnt++;
    e[ecnt] = p; cap[ecnt] = f2; nxt[ecnt] = st[q]; st[q] = ecnt++;
}

bool bfs() {
    memset(h, -1, sizeof(h));
    queue<int> q;
    q.push(ST);
    h[ST] = 0;
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        for (int i = st[v]; i != -1; i = nxt[i]) {
            if (cap[i] > 0 && h[e[i]] == -1) {
                q.push(e[i]);
                h[e[i]] = h[v] + 1;
            }
        }
    }
    return h[FN] != -1;
}

int dfs(int v, int f) {
    if (v == FN || f == 0) return f;
    for (int& i = cur[v]; i != -1; i = nxt[i]) {
        if (h[e[i]] == h[v] + 1 && cap[i] > 0) {
            int df = dfs(e[i], min(f, cap[i]));
            if (df > 0) {
                cap[i] -= df;
                cap[i^1] += df;
                return df;
            }
        }
    }
    return 0;
}

int Dinic() {
    int flow = 0;
    while (bfs()) {
        for (int i = 0; i < V; ++i) cur[i] = st[i];
        while (int add = dfs(ST, INF)) flow += add;
    }
    return flow;
}

void init() {
    memset(st, -1, sizeof(st));
    ecnt = 0;
}

bool ok(int i, int j) {
    return i >= 0 && i < ht && j >= 0 && j < wt && !block[i][j];
}

int main() {
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
    cin >> t;
    while (t--) {
        cin >> wt >> ht >> b;
        init();
        for (int i = 0; i < b; ++i) {
            int x, y;
            cin >> x >> y;
            block[y][x] = true;
        }

        V = wt * ht + 2;
        ST = V - 2;
        FN = V - 1;
        for (int i = 0; i < ht; ++i) {
            for (int j = 0; j < wt; ++j) {
                if (block[i][j]) continue;
                int v = i * wt + j;
                if (i == 0) add_edge(ST, v, 1, 0);
                if (i == ht - 1) add_edge(v, FN, 1, 0);
                for (int d = 0; d < 4; ++d) {
                    int ni = i + dx[d], nj = j + dy[d];
                    if (ok(ni, nj)) {
                        int nv = ni * wt + nj;
                        add_edge(v, nv, 1, 1); // Making it Bidirectional
                    }
                }
            }
        }

        cout << Dinic() << '\n';

        // Clearing blocks for the next scenario
        memset(block, 0, sizeof(block));
    }
    return 0;
}
