bool used[10];

void initialize() {
    int x, y;
    scanf("%d", &n);
    for(int i = 0; i < n; i++)
        for(int j = 0; j < n; j++)
            A[i][j] = false;
    for(int i = 1; i < n; i++) {
        scanf("%d%d", &x, &y);
        A[x-1][y-1] = A[y-1][x-1] = true;
    }

    scanf("%d", &m);
    for(int i = 0; i < m; i++)
        for(int j = 0; j < m; j++)
            B[i][j] = false;
    for(int i = 1; i < m; i++) {
        scanf("%d%d", &x, &y);
        B[x-1][y-1] = B[y-1][x-1] = true;
    }
}

bool match(int p, int q) {
    // Verify if all adjacencies of q in B are mirrored in A
    for(int i = 0; i < m; i++)
        if(B[q][i] && !A[f[q]][f[i]])
            return false;
    return true;
}

bool commenceSearch(int p) {
    if(p == m) return true; // All nodes successfully paired

    for(int i = 0; i < n; i++) {
        if(!used[i]) {
            f[p] = i;
            used[i] = true;
            if(match(p, p) && commenceSearch(p + 1)) return true;
            used[i] = false; // Revert for another trial
        }
    }

    return false;
}

void computeSolution() {
    for(int i = 0; i < n; i++) used[i] = false;
    if(commenceSearch(0)) printf("YES\n");
    else printf("NO\n");
}

