    // Uncomment for handling file input/output
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    int T;
    scanf("%d", &T);
    while(T--) {
        initialize();
        computeSolution();
    }
    return 0;
}
